cat > src/error.rs <<'EOF'
//! Error codes and the error value carried by failure responses.

use std::fmt;

use serde::Serialize;

/// The closed set of error codes miniq ever returns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum ErrorCode {
    /// The line is not a JSON object with a known string `Command`.
    InvalidRequest,
    /// A required parameter is absent.
    MissingParameter,
    /// A parameter or attribute has the wrong type or an unacceptable value.
    InvalidParameterValue,
    /// `CreateQueue` was given a name that breaks the naming rules.
    QueueNameInvalid,
    /// `CreateQueue` named an existing queue with different attributes.
    QueueAlreadyExists,
    /// The named queue, or dead-letter queue, does not exist.
    QueueDoesNotExist,
    /// The receipt handle was never issued.
    ReceiptHandleInvalid,
    /// The receipt handle was issued but cannot be used any more.
    ReceiptHandleExpired,
    /// The queue type does not support the request.
    UnsupportedOperation,
    /// The queue or message limit is reached.
    LimitExceeded,
}

/// A failed command: a code from the specification and a readable message.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Error {
    code: ErrorCode,
    message: String,
}

impl Error {
    /// Builds an error with the given code.
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    /// The code reported to the client.
    #[must_use]
    pub fn code(&self) -> ErrorCode {
        self.code
    }

    pub(crate) fn missing(parameter: &str) -> Self {
        Self::new(
            ErrorCode::MissingParameter,
            format!("parameter {parameter} is required"),
        )
    }

    pub(crate) fn invalid(parameter: &str, reason: impl fmt::Display) -> Self {
        Self::new(
            ErrorCode::InvalidParameterValue,
            format!("parameter {parameter} {reason}"),
        )
    }

    pub(crate) fn no_queue(name: &str) -> Self {
        Self::new(
            ErrorCode::QueueDoesNotExist,
            format!("queue {name:?} does not exist"),
        )
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}: {}", self.code, self.message)
    }
}

impl std::error::Error for Error {}
EOF
cat > src/reply.rs <<'EOF'
//! The shapes of success and failure responses.

use serde::Serialize;

use crate::error::Error;

/// The result members of a successful command.
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum Reply {
    /// A command with no result members.
    Empty {},
}

/// One response line.
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum Response {
    /// `{"ok": true, ...}`
    Success {
        /// Always true.
        ok: bool,
        /// The command's result members.
        #[serde(flatten)]
        reply: Reply,
    },
    /// `{"ok": false, "error": {...}}`
    Failure {
        /// Always false.
        ok: bool,
        /// What went wrong.
        error: Error,
    },
}

impl Response {
    pub(crate) fn success(reply: Reply) -> Self {
        Self::Success { ok: true, reply }
    }

    pub(crate) fn failure(error: Error) -> Self {
        Self::Failure { ok: false, error }
    }
}
EOF
cat > src/service.rs <<'EOF'
//! The process-wide state and command execution.

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode};
use crate::reply::{Reply, Response};

/// All state of one miniq process.
#[derive(Debug, Default)]
pub struct Service {}

impl Service {
    /// Runs one input line and returns the response to print.
    pub fn handle_line(&mut self, line: &[u8]) -> Response {
        match self.execute(line) {
            Ok(reply) => Response::success(reply),
            Err(error) => Response::failure(error),
        }
    }

    fn execute(&mut self, line: &[u8]) -> Result<Reply, Error> {
        let request: Map<String, Value> = serde_json::from_slice(line).map_err(|source| {
            Error::new(
                ErrorCode::InvalidRequest,
                format!("line is not a JSON object: {source}"),
            )
        })?;
        match request.get("Command") {
            Some(Value::String(name)) => Err(Error::new(
                ErrorCode::InvalidRequest,
                format!("unknown command {name:?}"),
            )),
            _ => Err(Error::new(
                ErrorCode::InvalidRequest,
                "member Command must be a string",
            )),
        }
    }
}
EOF
cat > src/lib.rs <<'EOF'
//! miniq: a small in-memory message queue driven by JSON lines.

mod error;
mod reply;
mod service;

use std::io::{self, BufRead, Write};

pub use error::{Error, ErrorCode};
pub use reply::{Reply, Response};
pub use service::Service;

/// Answers every line of `input` with one response line on `output`.
///
/// Each response is flushed before the next line is read. A final line
/// without a newline counts when it is not empty.
pub fn run<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
    let mut service = Service::default();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = service.handle_line(&line);
        serde_json::to_writer(&mut output, &response)?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}
EOF
cat > src/main.rs <<'EOF'
use std::io;
use std::process::ExitCode;

fn main() -> ExitCode {
    match miniq::run(io::stdin().lock(), io::stdout().lock()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("miniq: {error}");
            ExitCode::FAILURE
        }
    }
}
EOF
cat > tests/protocol.rs <<'EOF'
use miniq::run;
use serde_json::{Value, json};

fn session(input: &[u8]) -> Vec<Value> {
    let mut out = Vec::new();
    run(input, &mut out).expect("in-memory io cannot fail");
    String::from_utf8(out)
        .expect("responses are UTF-8")
        .lines()
        .map(|line| serde_json::from_str(line).expect("each response is one JSON line"))
        .collect()
}

fn invalid_request() -> Value {
    json!({"ok": false, "error": {"code": "InvalidRequest", "message": "x"}})
}

fn code_of(response: &Value) -> &Value {
    &response["error"]["code"]
}

#[test]
fn every_line_gets_one_response_including_blank_and_unterminated_ones() {
    let responses = session(b"\n{}\n[1]");
    assert_eq!(responses.len(), 3);
    for response in &responses {
        assert_eq!(response["ok"], json!(false));
        assert_eq!(code_of(response), &json!("InvalidRequest"));
    }
}

#[test]
fn empty_input_produces_no_output() {
    assert_eq!(session(b""), Vec::<Value>::new());
}

#[test]
fn malformed_requests_are_invalid_request() {
    let inputs: [&[u8]; 6] = [
        b"not json\n",
        b"{\"Command\": 5}\n",
        b"{\"Command\": null}\n",
        b"{\"Command\": \"Nope\"}\n",
        b"{\"Command\": \"Tick\"} trailing\n",
        b"{\"Command\": \"\xff\"}\n",
    ];
    for input in inputs {
        let responses = session(input);
        assert_eq!(responses.len(), 1, "input {input:?}");
        assert_eq!(code_of(&responses[0]), &json!("InvalidRequest"), "input {input:?}");
        assert_eq!(responses[0]["ok"], invalid_request()["ok"]);
    }
}
EOF
